#include "can_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void can_pclk_div (Pclk_Div pclk_div)
{
  switch (pclk_div)
    {
      case CCLK_DIV1 : 
        {
          PCLKSEL0 &= ~((UInt32) 0x3F << 26) ;
          PCLKSEL0 |= (UInt32) CCLK_DIV1 << 26 ;  // CLK = CCLK / 1  for CAN 1,2 and CAN filters
          break ;
        }
      case CCLK_DIV2 : 
        {
          PCLKSEL0 &= ~((UInt32) 0x3F << 26) ;
          PCLKSEL0 |= (UInt32) CCLK_DIV2 << 26 ;  // CLK = CCLK / 2  for CAN 1,2 and CAN filters
          break ;
        }
      case CCLK_DIV4 : 
        {
          PCLKSEL0 &= ~((UInt32) 0x3F << 26) ;
          PCLKSEL0 |= (UInt32) CCLK_DIV4 << 26 ;  // CLK = CCLK / 4  for CAN 1,2 and CAN filters
          break ;
        }
      case CCLK_DIV6 : 
        {
          PCLKSEL0 &= ~((UInt32) 0x3F << 26) ;
          PCLKSEL0 |= (UInt32) CCLK_DIV6 << 26 ;  // CLK = CCLK / 6  for CAN 1,2 and CAN filters
          break ;
        }
      default :
        {
          for (;;)
           {
             PCLKSEL0 &= ~((UInt32) 0x3F << 26) ;
           }
        }	
    }  
}
